{(\textbf{Adjustment set}; \citealp{maathuis2013generalized})}
   Let $\g$ represent a $\mathrm{DAG}$, $\mathrm{CPDAG}$, $\mathrm{MAG}$ or $\mathrm{PAG}$. Then $\mathbf{Z}$ is an adjustment set relative to ($\mathbf{X,Y}$) in $\g$  if for any density $f$ consistent with $\g$ we have
   \resizebox{19.5pc}{!}{
   $
   f(\mathbf{y}|do(\mathbf{x}))=
   \begin{cases}
   f(\mathbf{y}|\mathbf{x}) & \text{if }\mathbf{Z} = \emptyset,\\
   \int_{\mathbf{Z}}f(\mathbf{y}|\mathbf{x,z})f(\mathbf{z})d\mathbf{z} = E_{\mathbf{Z}}\{ f(\mathbf{y}|\mathbf{z,x})\} & \text{otherwise.}
   \end{cases}
   $
   }
   If $\mathbf{X} = \{X\}$ and $\mathbf{Y} = \{Y\}$, we call $\mathbf{Z}$ an adjustment set relative to $(X,Y)$ in the given graph.
   \label{defadjustment}

{(\textbf{Amenability for $DAG$s, $CPDAG$s, $MAG$s and $PAG$s})}
  A $\mathrm{DAG}$, $\mathrm{CPDAG}$, $\mathrm{MAG}$ or $\mathrm{PAG}$ $\g$ is said to be adjustment amenable, relative to $(\mathbf{X},\mathbf{Y})$ if every possibly directed proper path from $\mathbf{X}$ to $\mathbf{Y}$ in $\g$ starts with a visible edge out of $\mathbf{X}$.
  \label{defadjamengen}

{(\textbf{Generalized Adjustment Criterion (GAC)})}
   Let $\g$ represent a $\mathrm{DAG}$, $\mathrm{CPDAG}$, $\mathrm{MAG}$ or $\mathrm{PAG}$. Then $\mathbf{Z}$ satisfies the generalized adjustment criterion
      relative to $(\mathbf{X,Y})$ in $\g$ if the following three conditions hold:
   \begin{itemize}
   \item[(0)] $\g$ is adjustment amenable relative to ($\mathbf{X,Y}$), and
   \item[(1)] no element in $\mathbf{Z}$ is a possible descendant in $\g$ of any $W \in \vars\setminus\mathbf{X}$ which lies on a proper possibly causal path from $\mathbf{X}$ to $\mathbf{Y}$, and
   \item[(2)] all proper definite status non-causal paths in $\g$ from $\mathbf{X}$ to $\mathbf{Y}$ are blocked by $\mathbf{Z}$.
   \end{itemize}
   \label{defacgen}

\begin{align}\label{eq: def forbidden nodes}
